\label{FL3term}
	Let $\Omega\subset\mathbb{R}^d$ ($d\ge 2$) be a bounded domain with Lipschitz boundary. For each $\gamma>0$, there exists a constant $\Lambda(\Omega,\gamma)>0$ such that for all $\lambda > \Lambda(\Omega,\gamma)$,
	\begin{equation*}
		\sum_{\mu_k(\Omega)< \lambda} (\lambda-\mu_k(\Omega))^\gamma\ge L_{\gamma,d}|\Omega| \lambda^{\gamma+\frac{d}{2}}+ \frac{1}{5} L_{\gamma,d-1} |\partial \Omega| \lambda^{\gamma+\frac{d-1}{2}}.
	\end{equation*}

\label{lwsquare}
	For every $\gamma\ge \frac12$ and $\lambda>0$,
	\[
	\sum_{\substack{i\in\mathbb{Z}_{\ge0}, i^2<\lambda}}
	(\lambda-i^2)^\gamma
	\ge
	 L_{\gamma,1}\pi\lambda^{\gamma+\frac12}
	+\left(1-\frac{\pi}{4}\right)\lambda^\gamma.
	\]

Let $E_i=\operatorname{span}\{\varphi_0,\varphi_1,\ldots,\varphi_i\}.$ 
	By \eqref{minmax},
	\begin{equation}\label{genmax1}
		\mu_i(\Omega')
		\le
		\max_{\substack{f\in E_i\\f\neq0}}
		\frac{\displaystyle\int_{\Omega'}|\nabla f|^2\,dx}
		{\displaystyle\int_{\Omega'}f^2\,dx}.
	\end{equation}
	Write $
	f=\sum_{j=0}^i\alpha_j\varphi_j.$ 
	Then $
	\|f\|_{L^\infty(\Omega)}
	\le
	\Phi\sum_{j=0}^i|\alpha_j|$ and hence
	\begin{align*}
		\frac{\displaystyle\int_{\Omega'}|\nabla f|^2\,dx}
		{\displaystyle\int_{\Omega'}f^2\,dx}
		&\le
		\frac{\displaystyle\int_{\Omega}|\nabla f|^2\,dx}
		{\displaystyle\int_{\Omega}f^2\,dx
			-a^n|U|\Phi^2\cdot\left(\sum_{j=0}^i|\alpha_j|\right)^2}\\
		&=
		\frac{\displaystyle\int_{\Omega}|\nabla f|^2\,dx}
		{\displaystyle\int_{\Omega}f^2\,dx}
		\cdot
		\frac{\displaystyle\int_{\Omega}f^2\,dx}
		{\displaystyle\int_{\Omega}f^2\,dx
			-a^n|U|\Phi^2\cdot\left(\sum_{j=0}^i|\alpha_j|\right)^2}\\
		&\le
		\mu_i(\Omega)
		\cdot
		\frac{\sum_{j=0}^i|\alpha_j|^2}
		{\sum_{j=0}^i|\alpha_j|^2
			-a^n|U|\Phi^2(i+1)\sum_{j=0}^i|\alpha_j|^2}\\
		&\le
		\frac{\mu_i(\Omega)}{1-\epsilon}.
	\end{align*}
	The conclusion follows from \eqref{genmax1}.

