\label{thm:cuboid}
	With the notations above, set 
	\[
	\Lambda_2 := \left( \frac{8M}
	{(4-\pi)L_{0,n-1}|\widetilde\mathcal{R}|}
	\right)^{\frac2{n-1}}  
	\quad \text{ and } \quad 
	N_2 := L_{0,n}\pi^n\Lambda_2^{\frac n2}
	+ 2n\Lambda_2^{\frac{n-1}{2}}.
	\] 	
	Then the Neumann eigenvalues of $\mathcal{R}' = \mathcal{R}\setminus \overline{\cup_{i=1}^MQ_i}$
	satisfy P\'olya's conjecture provided
	\[
	\mathcal A_{\mathcal Q}=
	\sum_{k=1}^M\ell(Q_k)^{n-1}
	<
	\frac{(4-\pi)\pi^{n-1}L_{0,n-1}
		|\widetilde\mathcal{R}|}{16n}
	\]
	and
	\[
	\mathcal V_{\mathcal Q}=\sum_{k=1}^M \ell(Q_k)^n
	<
	\frac{|\mathcal{R}|}{2^nN_2}
	\min\left(
	\frac{(4-\pi)L_{0,n-1}}
	{4L_{0,n}\sqrt{\Lambda_2}\,n\pi},
	\frac1n
	\right).
	\]

\label{lem:strict-blichfeldt-ball}
	Let $n\ge2$, let $\Lambda\subset\mathbb{R}^n$ be a full-rank lattice with covolume $d_\Lambda$, and let $r>0$.   
	Then there exists a translation $\theta\in\mathbb{R}^n$ such that
	\begin{equation}\label{eq:blichfeldt-ceil}
		\#\bigl((\Lambda+\theta)\cap B_r\bigr)\ge \left[\frac{|B_r|}{d_\Lambda}+1\right].
	\end{equation}

\label{lem:periodic-plane-waves}
	Let $C$ be the translational supertile in Definition \ref{def:periodic}, and let
	\[
	\Gamma^*:=\{\xi\in\mathbb{R}^n:\xi\cdot\gamma\in2\pi\mathbb Z
	\text{ for every }\gamma\in\Gamma\}
	\]
	be the dual lattice.  Then for every $\theta\in\mathbb{R}^n$ and every $\lambda>0$,
	\begin{equation}\label{eq:plane-wave-bracket}
		\#\{\xi\in\Gamma^*:|\xi+\theta|^2<\lambda\}
		\le N_C^N(\lambda)
		\le \ell N_\Omega^N(\lambda).
	\end{equation}

\label{lem:periodic-strict}
	Let $n\ge2$ and let $\Omega\subset\mathbb{R}^n$ be a bounded periodic Euclidean tiling domain with compact Neumann embedding.  Then
	\begin{equation}\label{eq:periodic-strict}
		N^N_\Omega(\lambda)>L_{0,n}|\Omega|\lambda^{\frac n2},\qquad \lambda>0.
	\end{equation}

\label{genlem}
	\begin{enumerate}
		\item The $N_L$ copies of $\Omega$, together with $A_L$, tile $R_{L+2}$ in the sense that the closure of their union equals $\overline{R_{L+2}}$ and they are pairwise disjoint.
		\item The $N_L'$ copies of $\Omega$, together with $B_L$, cover $A_L$. Moreover, every point in $A_L$ is contained in at most two elements of this cover.
		\item The set $B_L$ can be partitioned into $(2L+4)^{n_2}-(2L+2)^{n_2}$ pairwise disjoint copies of $
		\widetilde U:= U\times (0,1)^{n_2}.$
	\end{enumerate}

\label{thm:neumann-disk-supnorm}
	Every \(\varphi\in\mathcal B \setminus \{\varphi_0\}\)   satisfies
	\[
	\|\varphi\|_{L^\infty(\mathbb{D})}
	\leq 2\,\lambda^{\frac 14}.
	\]

By \eqref{eq:BesselFunctionInt},   $|J_n(x)|\leq 1$ for all $n$ and all $x\in\mathbb R$. 
	So if $n=0$, Lemma~\ref{lem:bessel-critical-value} gives  
	\[
	\|\varphi_{0,k}\|_{L^\infty(\mathbb D)}
	\le  \frac{1}{\sqrt\pi\,|J_0(j'_{0,k})|}
	\leq \frac{2}{\sqrt\pi}\sqrt{j'_{0,k}}
	<2\lambda_{0,k+1}^{\frac 14}.
	\]
	Now fix $n,k\geq1$                         
	and write
	\[
	M=M_n(j'_{n,k})=\max_{0\leq x\leq j'_{n,k}}|J_n(x)|.
	\]
	Suppose first that $j'_{n,k}<2n$.  Apply 
	Lemma~\ref{lem:bessel-near-turning} to $a=j'_{n,k}$, 
	\[
	\int_0^1J_n(j'_{n,k}r)^2r\,dr = \frac{1}{{j'_{n,k}}^2}\int_0^{j'_{n,k}} xJ_n(x)^2\,dx \geq \frac{nM^2}{4{j'_{n,k}}^2}.
	\]
	Since the angular factors have \(L^2\)-norm squared \(\pi\) and
	\(L^\infty\)-norm \(1\), we obtain
	\begin{align*}

		\|\varphi_{n,k}^{c,s}\|_{L^\infty(\mathbb D)} 
		\leq
		\frac{M}
		{\left(
			\pi\int_0^1J_n(j'_{n,k}r)^2r\,dr
			\right)^{1/2}} \leq
		\frac{2j'_{n,k}}{\sqrt{\pi n}}
		<
		2\lambda_{n,k}^{\frac14},
	\end{align*}
	where the last inequality follows from $j'_{n,k}<2n<\pi n$.

	Finally, if $j'_{n,k}\geq2n$, then 
	$1-n^2/{j'_{n,k}}^2\geq3/4$.  Lemma~\ref{lem:bessel-critical-value} and  $|J_n(x)|\leq 1$ imply
	\begin{align*}
		\|\varphi_{n,k}^{c,s}\|_{L^\infty(\mathbb D)} 
		\le C_{n,k} = 
		\left(\frac{2}{\pi}\right)^{1/2}
		\frac{1}
		{\sqrt{1-n^2/{j'_{n,k}}^2}\,|J_n(j'_{n,k})|} \leq
		4\sqrt{\frac{2}{3\pi}}\sqrt{j'_{n,k}}< 2\lambda_{n,k}^{\frac 14}.
	\end{align*}
	This completes the proof.

\label{cor:coppercoin}
	For every \(0<a<9\times10^{-8}\), the Neumann eigenvalues of 
	\[
	\mathbb D\setminus\overline{(0,a)\times(0,a)}
	\]
	satisfy P\'olya's conjecture.
